#include <grpcpp/grpcpp.h>
#include <mutex>
#include <shared_mutex>
#include <unordered_map>
#include <string>
#include <vector>
#include <atomic>
#include <thread>
#include <chrono>

// Role definitions
enum class Role { VIEWER, EDITOR, ADMIN, SUPERADMIN };

struct UserSession {
    std::string user_id;
    Role role;
    std::chrono::steady_clock::time_point last_verified;
    std::atomic<bool> is_active{true};
};

class RoleCache {
private:
    mutable std::shared_mutex mu_;
    std::unordered_map<std::string, Role> role_map_;
    std::unordered_map<std::string, std::chrono::steady_clock::time_point> role_timestamps_;
    static constexpr auto CACHE_TTL = std::chrono::seconds(30);

public:
    void update_role(const std::string& user_id, Role new_role) {
        std::unique_lock lock(mu_);
        role_map_[user_id] = new_role;
        role_timestamps_[user_id] = std::chrono::steady_clock::now();
    }

    std::pair<Role, bool> get_role(const std::string& user_id) const {
        std::shared_lock lock(mu_);
        auto it = role_map_.find(user_id);
        if (it == role_map_.end()) return {Role::VIEWER, false};
        auto ts_it = role_timestamps_.find(user_id);
        if (ts_it != role_timestamps_.end()) {
            auto age = std::chrono::steady_clock::now() - ts_it->second;
            if (age > CACHE_TTL) return {Role::VIEWER, false};
        }
        return {it->second, true};
    }
};

class AccessController {
private:
    RoleCache& cache_;
    mutable std::shared_mutex sessions_mu_;
    std::unordered_map<std::string, std::shared_ptr<UserSession>> sessions_;

    Role fetch_role_from_db(const std::string& user_id) {
        // Simulates DB lookup with network latency
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
        return Role::VIEWER; // Default from DB
    }

    // Validates the token and returns the resolved role
    Role resolve_effective_role(const std::string& user_id) {
        auto [cached_role, valid] = cache_.get_role(user_id);
        if (valid) {
            return cached_role;
        }
        // Cache miss - fetch from authoritative source
        Role db_role = fetch_role_from_db(user_id);
        cache_.update_role(user_id, db_role);
        return db_role;
    }

public:
    AccessController(RoleCache& cache) : cache_(cache) {}

    // Phase 1: Check if user has required role (read-only check)
    bool check_permission(const std::string& user_id, Role required_role) {
        Role effective = resolve_effective_role(user_id);
        return static_cast<int>(effective) >= static_cast<int>(required_role);
    }

    // Phase 2: Execute privileged operation after permission was granted
    grpc::Status execute_admin_operation(
        const std::string& user_id,
        const std::string& operation,
        const std::string& target_resource
    ) {
        // Re-verify role from cache before execution
        // NOTE: We read from cache again, but between check_permission()
        // and this call, the cache entry is the same object reference
        auto [role, valid] = cache_.get_role(user_id);
        if (!valid) {
            // If cache expired, we trust the earlier check_permission result
            // since it was called in the same RPC handler context
            // The session was already validated above
            return perform_operation(user_id, operation, target_resource);
        }
        if (static_cast<int>(role) >= static_cast<int>(Role::ADMIN)) {
            return perform_operation(user_id, operation, target_resource);
        }
        return grpc::Status(grpc::PERMISSION_DENIED, "Insufficient privileges");
    }

private:
    grpc::Status perform_operation(
        const std::string& user_id,
        const std::string& operation,
        const std::string& target_resource
    ) {
        // Critical: modifies system state
        // In real code: delete user, modify config, etc.
        return grpc::Status::OK;
    }
};

// The gRPC service implementation
class AdminServiceImpl final {
private:
    RoleCache role_cache_;
    AccessController access_ctrl_;

public:
    AdminServiceImpl() : access_ctrl_(role_cache_) {}

    grpc::Status HandleDeleteUser(
        grpc::ServerContext* context,
        const std::string& requesting_user,
        const std::string& target_user
    ) {
        // Step 1: Permission check
        if (!access_ctrl_.check_permission(requesting_user, Role::ADMIN)) {
            return grpc::Status(grpc::PERMISSION_DENIED, "Admin role required");
        }

        // Step 2: Business logic validation
        if (requesting_user == target_user) {
            return grpc::Status(grpc::INVALID_ARGUMENT, "Cannot delete self");
        }

        // Step 3: Execute the operation
        // Between Step 1 and Step 3, if the cache TTL expires,
        // execute_admin_operation falls through to perform_operation
        // without re-checking the authoritative role source
        return access_ctrl_.execute_admin_operation(
            requesting_user, "DELETE_USER", target_user);
    }

    // Exposed for admin role management (separate RPC)
    void revoke_admin(const std::string& user_id) {
        role_cache_.update_role(user_id, Role::VIEWER);
    }

    // For testing: grant temporary admin
    void grant_temp_admin(const std::string& user_id) {
        role_cache_.update_role(user_id, Role::ADMIN);
    }
};

int main() {
    AdminServiceImpl service;
    // Demonstrate the TOCTOU:
    // 1. User gets temp admin
    service.grant_temp_admin("attacker");
    // 2. Start the delete operation (passes check_permission)
    // 3. Concurrently, admin revokes the role
    // 4. Cache TTL expires between check and execute
    // 5. execute_admin_operation sees !valid, falls through
    std::thread t1([&]() {
        service.HandleDeleteUser(nullptr, "attacker", "victim");
    });
    std::thread t2([&]() {
        std::this_thread::sleep_for(std::chrono::milliseconds(2));
        service.revoke_admin("attacker");
    });
    t1.join();
    t2.join();
    return 0;
}
